def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr() -> int | str:
        nonlocal i
        val = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                break
            op = s[i]
            i += 1
            rhs = parse_term()
            if val == "error" or rhs == "error":
                val = "error"
            elif op == "+":
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term() -> int | str:
        nonlocal i
        val = parse_factor()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                break
            op = s[i]
            i += 1
            rhs = parse_factor()
            if val == "error" or rhs == "error":
                val = "error"
            elif op == "*":
                val = val * rhs
            elif rhs == 0:
                val = "error"
            elif op == "/":
                val = trunc_div(val, rhs)
            else:
                val = val - rhs * trunc_div(val, rhs)
        return val

    def parse_factor() -> int | str:
        nonlocal i
        stack = []
        while True:
            skip()
            neg = 0
            while i < n and s[i] == "-":
                neg += 1
                i += 1
                skip()
            base = parse_primary()
            skip()
            if i < n and s[i] == "^":
                i += 1
                stack.append((neg, base))
                continue
            val = base
            if val != "error" and neg & 1:
                val = -val
            while stack:
                neg, base = stack.pop()
                if val == "error" or base == "error" or val < 0:
                    val = "error"
                else:
                    val = base ** val
                if val != "error" and neg & 1:
                    val = -val
            return val

    def parse_primary() -> int | str:
        nonlocal i
        skip()
        if s[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_expr()
